const tt=(lang:Lang,k:keyof typeof dictionary['en'])=>dictionary[lang][k]||dictionary.en[k];
function clampNum(v:string,min:number,max:number,step=1){const n=Number(v); if(!Number.isFinite(n)) return min; const r=Math.round((Math.max(min,Math.min(max,n))-min)/step)*step+min; return Number(r.toFixed(2));}
function deadlineClass(status:string){return status==='passed'?'danger':status==='upcoming'?'good':'neutral';}
function deadlineLabel(status:string,lang:Lang){return status==='passed'?tt(lang,'passed'):status==='upcoming'?tt(lang,'upcoming'):tt(lang,'unknown');}

export default function PathlyHome(){
  const store=usePathlyStore();
  const {profile,journey,selected,toggleSelected,completeTask,setProfile,recalculate,resetDemo}=store;
  const [mode,setMode]=useState<PublicView>('landing');
  const [view,setView]=useState<View>('overview');
  const [lang,setLang]=useState<Lang>('en');
  const [theme,setTheme]=useState<Theme>('dark');
  const [density,setDensity]=useState<Density>('comfortable');
  const [sidebar,setSidebar]=useState(true); const [mobile,setMobile]=useState(false); const [settings,setSettings]=useState(false);const [chat,setChat]=useState(false); const [toast,setToast]=useState('');
  const [step,setStep]=useState(1); const [authTab,setAuthTab]=useState<'login'|'signup'>('signup');
  const [onboardingProfile,setOnboardingProfile]=useState<Profile>(goldenProfile);
  useEffect(()=>{const l=localStorage.getItem('pathly-lang') as Lang|null; const th=localStorage.getItem('pathly-theme') as Theme|null; const d=localStorage.getItem('pathly-size') as Density|null; const m=localStorage.getItem('pathly-mode') as PublicView|null; if(l)setLang(l); if(th)setTheme(th); if(d)setDensity(d); if(m)setMode(m)},[]);
  useEffect(()=>{document.documentElement.lang=lang;document.documentElement.dataset.theme=theme;document.documentElement.dataset.density=density;localStorage.setItem('pathly-lang',lang);localStorage.setItem('pathly-theme',theme);localStorage.setItem('pathly-size',density);localStorage.setItem('pathly-mode',mode)},[lang,theme,density,mode]);
  const notify=(m:string)=>{setToast(m);window.setTimeout(()=>setToast(''),1800)};
  const pct=Math.round((journey.roadmap.filter(x=>x.status==='done').length/Math.max(journey.roadmap.length,1))*100);
  const begin=()=>{setAuthTab('signup');setMode('auth');setStep(1)}; const openLogin=()=>{setAuthTab('login');setMode('auth')};
  if(mode==='landing') return <Landing lang={lang} setLang={setLang} theme={theme} setTheme={setTheme} onStart={begin} onLogin={openLogin} />;
  if(mode==='auth') return <Auth lang={lang} setLang={setLang} initialTab={authTab} onBack={()=>setMode('landing')} onEnter={()=>{setMode('onboarding');setStep(1)}} />;
  if(mode==='onboarding') return <Onboarding lang={lang} profile={onboardingProfile} setProfile={setOnboardingProfile} step={step} setStep={setStep} onBack={()=>step===1?setMode('landing'):setStep(step-1)} onFinish={()=>{setProfile(onboardingProfile);setMode('app');notify(tt(lang,'brief'));}} />;
  return <AppShell {...{lang,setLang,theme,setTheme,density,setDensity,sidebar,setSidebar,mobile,setMobile,settings,setSettings,chat,setChat,setMode,view,setView,toast,setToast,store,profile,journey,selected,toggleSelected,completeTask,setProfile,recalculate,resetDemo,pct,notify,onboardingProfile}}/>;
}

function Landing({lang,setLang,theme,setTheme,onStart,onLogin}:{lang:Lang;setLang:(x:Lang)=>void;theme:Theme;setTheme:(x:Theme)=>void;onStart:()=>void;onLogin:()=>void}){
 return <div className="public-shell"><header className="public-nav"><button className="brand public-brand"><span className="brand-mark"><Sparkles size={17}/></span><span><b>Pathly</b><small>admission workspace</small></span></button><nav><a href="#why">{tt(lang,'why')}</a><a href="#how">{tt(lang,'how')}</a><a href="#stories">{tt(lang,'stories')}</a></nav><div className="public-actions"><LanguageMenu lang={lang} setLang={setLang}/><button className="icon-btn" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={17}/>:<Moon size={17}/>}</button><button className="ghost-btn" onClick={onLogin}>{tt(lang,'login')}</button><button className="primary-btn" onClick={onStart}>{tt(lang,'start')}<ArrowRight size={15}/></button></div></header>
 <main className="landing-main"><section className="landing-hero"><div className="hero-copy"><span className="eyebrow"><Sparkles size={14}/> PERSONAL ADMISSION OS</span><h1>{tt(lang,'hero')}</h1><p>{tt(lang,'heroSub')}</p><div className="hero-cta"><button className="primary-btn xl" onClick={onStart}>{tt(lang,'start')}<ArrowRight size={17}/></button><button className="secondary-btn xl" onClick={onLogin}><LogIn size={16}/>{tt(lang,'login')}</button></div><div className="trust-row"><span><ShieldCheck size={14}/> profile-aware</span><span><Globe2 size={14}/> global discovery</span><span><Target size={14}/> action-first</span></div></div><div className="orbit-card"><div className="orbit-glow"/><div className="journey-orbit"><span className="orbit-node n1">Profile</span><span className="orbit-node n2">Fit</span><span className="orbit-node n3">Compare</span><span className="orbit-node n4">Roadmap</span><div className="orbit-center"><Sparkles size={24}/><b>Pathly</b><small>one journey</small></div></div></div></section>
 <section id="how" className="section-wide"><div className="section-title"><span className="eyebrow">01</span><h2>{tt(lang,'how')}</h2></div><div className="feature-grid"><Feature icon={<User size={18}/>} title="1. Profile" text="Set your grade, GPA, IELTS, SAT, goals, budget and constraints."/><Feature icon={<Sparkles size={18}/>} title="2. AI Brief" text="See your strengths, gaps and the factors shaping your route."/><Feature icon={<Compass size={18}/>} title="3. Recommendations" text="Explore programs with an explainable Pathly Fit and source status."/><Feature icon={<ListChecks size={18}/>} title="4. Roadmap" text="Turn the choice into deadlines, documents and one next move."/></div></section>
 <section id="why" className="section-wide split-public"><div><span className="eyebrow">02</span><h2>{tt(lang,'why')}</h2><p>{tt(lang,'heroSub')}</p><div className="bullet-stack"><span><CheckCircle2 size={16}/> No generic university dump.</span><span><CheckCircle2 size={16}/> Your results recalculate when your inputs change.</span><span><CheckCircle2 size={16}/> Current deadline status is separated from fit.</span></div></div><div className="quote-card"><Quote size={26}/><p>“The useful part was not finding more universities. It was seeing what I should do next.”</p><small>— Pathly pilot student</small></div></section>
 <section id="stories" className="section-wide"><div className="section-title"><span className="eyebrow">03</span><h2>{tt(lang,'studentStories')}</h2></div><div className="story-grid"><Story title={tt(lang,'story1')} num="01"/><Story title={tt(lang,'story2')} num="02"/><Story title={tt(lang,'story3')} num="03"/></div></section>
 <section className="cta-band"><div><span className="eyebrow">READY?</span><h2>{tt(lang,'hero')}</h2><p>{tt(lang,'heroSub')}</p></div><button className="primary-btn xl" onClick={onStart}>{tt(lang,'start')}<ArrowRight size={17}/></button></section></main><footer className="public-footer"><span>Pathly © 2026</span><span>Admissions should feel like a journey, not a maze.</span></footer></div>
}

function Feature({icon,title,text}:{icon:any;title:string;text:string}){return <article className="public-card"><div className="feature-icon">{icon}</div><h3>{title}</h3><p>{text}</p></article>}
function Story({title,num}:{title:string;num:string}){return <article className="story-card"><span>{num}</span><h3>{title}</h3><p>One connected flow. Less noise. More deliberate progress.</p></article>}

function Auth({lang,setLang,onBack,onEnter,initialTab}:{lang:Lang;setLang:(x:Lang)=>void;onBack:()=>void;onEnter:()=>void;initialTab:'login'|'signup'}){const [tab,setTab]=useState<'login'|'signup'>(initialTab); useEffect(()=>setTab(initialTab),[initialTab]);return <div className="public-shell auth-shell"><header className="public-nav"><button className="brand public-brand" onClick={onBack}><span className="brand-mark"><Sparkles size={17}/></span><span><b>Pathly</b><small>admission workspace</small></span></button><div className="public-actions"><LanguageMenu lang={lang} setLang={setLang}/></div></header><main className="auth-main"><div className="auth-card"><div className="seg-tabs"><button className={tab==='login'?'active':''} onClick={()=>setTab('login')}>{tt(lang,'login')}</button><button className={tab==='signup'?'active':''} onClick={()=>setTab('signup')}>{tt(lang,'signup')}</button></div><div className="auth-head"><span className="eyebrow"><LockKeyhole size={13}/> PATHLY ACCOUNT</span><h1>{tab==='login'?tt(lang,'login'):tt(lang,'signup')}</h1><p>{tt(lang,'tagline')}</p></div><label className="field"><span>{tt(lang,'email')}</span><div className="input-icon"><Mail size={15}/><input type="email" placeholder="you@example.com" /></div></label><label className="field"><span>{tt(lang,'password')}</span><div className="input-icon"><LockKeyhole size={15}/><input type="password" placeholder="••••••••" /></div></label><button className="primary-btn wide" onClick={onEnter}>{tt(lang,'continue')}<ArrowRight size={15}/></button><div className="divider"><span>or</span></div><button className="secondary-btn wide" onClick={onEnter}><Globe2 size={15}/>{tt(lang,'signInWithGoogle')}</button><p className="auth-switch">{tab==='login'?tt(lang,'newHere'):tt(lang,'already')} <button onClick={()=>setTab(tab==='login'?'signup':'login')}>{tab==='login'?tt(lang,'signup'):tt(lang,'login')}</button></p></div></main></div>}

function Onboarding({lang,profile,setProfile,step,setStep,onBack,onFinish}:{lang:Lang;profile:Profile;setProfile:(x:Profile)=>void;step:number;setStep:(n:number)=>void;onBack:()=>void;onFinish:()=>void}){
 const update=(patch:Partial<Profile>)=>setProfile({...profile,...patch});
 const stepData=[
  {title:'Your academic profile',sub:'Start with the facts. We will turn them into a route.'},
  {title:'Your direction',sub:'Tell Pathly what you want to study and where.'},
  {title:'Your constraints',sub:'Budget and funding change what is practical.'}
 ];
 return <div className="public-shell"><header className="public-nav onboarding-nav"><button className="brand public-brand"><span className="brand-mark"><Sparkles size={17}/></span><span><b>Pathly</b><small>admission workspace</small></span></button><div className="stepper-head">{stepData.map((x,i)=><span className={step===i+1?'active':''} key={x.title}><b>0{i+1}</b>{x.title}</span>)}</div></header><main className="onboarding-main"><div className="onboarding-shell"><div className="onboarding-intro"><span className="eyebrow">STEP {String(step).padStart(2,'0')}</span><h1>{stepData[step-1].title}</h1><p>{stepData[step-1].sub}</p></div><div className="onboarding-card card">{step===1&&<div className="form-grid big"><NumberField label={tt(lang,'age')} value={profile.age} min={14} max={100} step={1} onChange={v=>update({age:v})}/><Select label={tt(lang,'grade')} value={profile.grade} options={['Grade 9','Grade 10','Grade 11','Grade 12','Graduate']} onChange={v=>update({grade:v})}/><Select label={tt(lang,'degree')} value={profile.degree} options={['Bachelor','Master']} onChange={v=>update({degree:v as any})}/><NumberField label={tt(lang,'gpa')} value={profile.gpa} min={1} max={5} step={0.1} onChange={v=>update({gpa:v})}/><NumberField label={tt(lang,'ielts')} value={profile.ielts} min={0} max={9} step={0.5} onChange={v=>update({ielts:v})}/><NumberField label={tt(lang,'sat')} value={profile.sat} min={400} max={1600} step={10} onChange={v=>update({sat:v})}/></div>}{step===2&&<div className="form-grid big"><Select label={tt(lang,'major')} value={profile.major} options={majors} onChange={v=>update({major:v})}/><Select label={tt(lang,'country')} value={profile.country} options={countries} onChange={v=>update({country:v})}/><Select label={tt(lang,'year')} value={profile.targetYear} options={Array.from({length:5},(_,i)=>2026+i)} onChange={v=>update({targetYear:Number(v)})}/><Select label="Intake" value={profile.targetIntake} options={['Spring 2027','Fall 2027','Spring 2028','Fall 2028']} onChange={v=>update({targetIntake:v})}/><div className="full-span"><span className="field-label">{tt(lang,'interests')}</span><div className="tag-cloud">{['AI','Software','Research','Robotics','Entrepreneurship','Physics','Design','Data'].map(x=><button key={x} className={profile.interests.includes(x)?'tag active':'tag'} onClick={()=>update({interests:profile.interests.includes(x)?profile.interests.filter(i=>i!==x):[...profile.interests,x]})}>{x}</button>)}</div></div></div>}{step===3&&<div className="form-grid big"><BudgetField label={tt(lang,'budget')} value={profile.budget} onChange={v=>update({budget:v})}/><label className="field"><span>{tt(lang,'fully')}</span><button type="button" className={profile.fullyFunded?'choice-box active':'choice-box'} onClick={()=>update({fullyFunded:!profile.fullyFunded})}><span>{profile.fullyFunded?'ON':'OFF'}</span><small>Prioritize funding options</small></button></label><div className="full-span"><span className="field-label">Preferred countries</span><div className="country-cloud">{profile.preferredCountries.map(c=><button key={c} className="country-chip" onClick={()=>update({preferredCountries:profile.preferredCountries.filter(x=>x!==c)})}>{c}<X size={11}/></button>)}<CountryAdd profile={profile} update={update}/></div></div></div>}<div className="onboarding-footer"><button className="secondary-btn" onClick={onBack}>{<ChevronLeft size={15}/>} {tt(lang,'back')}</button>{step<3?<button className="primary-btn" onClick={()=>setStep(step+1)}>{tt(lang,'continue')}<ChevronRight size={15}/></button>:<button className="primary-btn" onClick={onFinish}>{tt(lang,'finish')}<Sparkles size={15}/></button>}</div></div></div></main></div>;
}

function AppShell({lang,setLang,theme,setTheme,density,setDensity,sidebar,setSidebar,mobile,setMobile,settings,setSettings,chat,setChat,setMode,view,setView,toast,setToast,profile,journey,selected,toggleSelected,completeTask,setProfile,recalculate,resetDemo,pct,notify}:{lang:Lang;setLang:(x:Lang)=>void;theme:Theme;setTheme:(x:Theme)=>void;density:Density;setDensity:(x:Density)=>void;sidebar:boolean;setSidebar:(x:boolean)=>void;mobile:boolean;setMobile:(x:boolean)=>void;settings:boolean;setSettings:(x:boolean)=>void;chat:boolean;setChat:(x:boolean)=>void;setMode:(x:any)=>void;view:View;setView:(x:View)=>void;toast:string;setToast:(x:string)=>void;profile:Profile;journey:any;selected:string[];toggleSelected:(id:string)=>void;completeTask:(id:string)=>void;setProfile:(x:Partial<Profile>)=>void;recalculate:()=>void;resetDemo:()=>void;pct:number;notify:(x:string)=>void}){
 const navGo=(v:View)=>{setView(v);setMobile(false);window.scrollTo({top:0,behavior:'smooth'})};
 return <div className="app-shell"><aside className={`sidebar ${sidebar?'':'collapsed'} ${mobile?'mobile-visible':''}`}><div className="brand-row"><button className="brand" onClick={()=>navGo('overview')}><span className="brand-mark"><Sparkles size={16}/></span>{sidebar&&<span><b>Pathly</b><small>admission workspace</small></span>}</button>{sidebar&&<button className="icon-btn" onClick={()=>setSidebar(false)}><PanelLeftClose size={16}/></button>}</div>{!sidebar&&<button className="icon-btn expand" onClick={()=>setSidebar(true)}><PanelLeftOpen size={16}/></button>}{sidebar&&<div className="mini-user"><div className="avatar">A</div><div><b>Alex</b><small>{profile.major}</small></div></div>}<div className="nav-label">{sidebar?'Workspace':''}</div><nav>{nav.map(n=>{const I=n.icon;return <button key={n.id} className={view===n.id?'nav-active':''} onClick={()=>navGo(n.id)}><I size={18}/>{sidebar&&<span>{n[lang]}</span>}{n.id==='shortlist'&&selected.length>0&&sidebar&&<em>{selected.length}</em>}</button>})}</nav><div className="side-bottom"><div className="side-tip"><Target size={14}/>{sidebar&&<><b>{tt(lang,'next')}</b><small>{journey.nextAction?.title||'—'}</small></>}</div><button className="ghost-reset" onClick={()=>{resetDemo();notify(tt(lang,'reset'))}}><RotateCcw size={15}/>{sidebar&&tt(lang,'reset')}</button></div></aside><div className="main-wrap"><header className="topbar"><div className="crumb"><button className="mobile-only icon-btn" onClick={()=>setMobile(!mobile)}><Menu size={19}/></button><span>Pathly</span><ChevronRight size={14}/><b>{nav.find(x=>x.id===view)?.[lang]}</b></div><div className="top-actions"><button className="top-link" onClick={()=>navGo('explore')}><Search size={17}/></button><button className="top-link"><Bell size={17}/></button><LanguageMenu lang={lang} setLang={setLang}/><button className="top-link" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={17}/>:<Moon size={17}/>}</button><button className="avatar small" onClick={()=>navGo('profile')}>A</button></div></header><main className="content"><div className="route-enter" key={`${view}-${lang}-${density}`}>{view==='overview'&&<Overview lang={lang} profile={profile} journey={journey} pct={pct} navGo={navGo}/>} {view==='explore'&&<Explore lang={lang} profile={profile} journey={journey} selected={selected} toggleSelected={toggleSelected} setProfile={setProfile} recalculate={recalculate}/>} {view==='shortlist'&&<Shortlist lang={lang} journey={journey} selected={selected} toggleSelected={toggleSelected}/>} {view==='roadmap'&&<Roadmap lang={lang} journey={journey} pct={pct} completeTask={completeTask}/>} {view==='funding'&&<Funding lang={lang} journey={journey}/>} {view==='profile'&&<ProfileView lang={lang} profile={profile} setProfile={setProfile} recalculate={()=>{recalculate();notify(tt(lang,'recalculate'))}}/>}</div></main><footer><span><ShieldCheck size={14}/>{tt(lang,'demo')} · {tt(lang,'source')}</span><span>Pathly © 2026</span></footer></div><button className="chat-fab" onClick={()=>setChat(true)} aria-label="Ask Pathly AI"><Sparkles size={18}/><span>Ask Pathly</span></button><button className="settings-fab" onClick={()=>setSettings(true)} aria-label="Settings"><Settings size={17}/></button>{chat&&<ChatModal lang={lang} profile={profile} close={()=>setChat(false)}/>} {settings&&<SettingsModal lang={lang} setLang={setLang} theme={theme} setTheme={setTheme} density={density} setDensity={setDensity} close={()=>setSettings(false)}/>} {toast&&<div className="toast"><Check size={14}/>{toast}</div>}</div>
}

function Overview({lang,profile,journey,pct,navGo}:{lang:Lang;profile:Profile;journey:any;pct:number;navGo:(v:View)=>void}){const top=journey.recommendations.slice(0,3);return <section><div className="hero-heading"><div><span className="eyebrow">PATHLY JOURNEY</span><h1>{tt(lang,'brief')}</h1><p>{journey.diagnosis.headline}</p></div><button className="primary-btn" onClick={()=>navGo('explore')}><Compass size={16}/>{tt(lang,'explore')}</button></div><div className="hero-grid"><div className="hero-card card"><div className="hero-card-top"><span className="live"><span/> ACTIVE</span><span className="muted">{profile.country} · {profile.grade}</span></div><div className="hero-metrics"><div><b>{journey.recommendations.length}</b><span>{tt(lang,'matches')}</span></div><div><b>{top[0]?.fit||0}</b><span>Pathly Fit</span></div><div><b>{pct}%</b><span>{tt(lang,'progress')}</span></div></div><div className="progress"><span style={{width:`${Math.max(6,pct)}%`}}/></div><div className="mini-meta"><span>{profile.major}</span><span>{profile.targetIntake}</span><span>{profile.fullyFunded?tt(lang,'fully'):'Budget-aware'}</span></div></div><div className="next-card card"><span className="eyebrow"><Target size={13}/>{tt(lang,'next')}</span><h3>{journey.nextAction?.title||'All caught up'}</h3><p>{journey.nextAction?.why||'Your roadmap is complete.'}</p><button className="secondary-btn" onClick={()=>navGo('roadmap')}>{tt(lang,'roadmap')}<ArrowRight size={15}/></button></div></div><div className="diagnosis-grid"><div className="card brief-card"><div className="section-head compact"><h3>{tt(lang,'strengths')}</h3><Sparkles size={16}/></div>{journey.diagnosis.strengths.map((x:string)=><div className="brief-row" key={x}><CheckCircle2 size={15}/><span>{x}</span></div>)}</div><div className="card brief-card"><div className="section-head compact"><h3>{tt(lang,'constraints')}</h3><CircleHelp size={16}/></div>{journey.diagnosis.constraints.map((x:string)=><div className="brief-row warn" key={x}><Target size={15}/><span>{x}</span></div>)}</div><div className="card brief-card"><div className="section-head compact"><h3>{tt(lang,'goal')}</h3><Trophy size={16}/></div><p className="goal-copy">{profile.goal.replace('-', ' ')}</p></div></div><AIInsightCard lang={lang} profile={profile} journey={journey}/><div className="section-head"><div><span className="eyebrow">01</span><h2>{tt(lang,'recommended')}</h2></div><button className="text-btn" onClick={()=>navGo('explore')}>{tt(lang,'seeAll')}<ArrowRight size={15}/></button></div><div className="program-grid">{top.map((p:ScoredProgram,i:number)=><ProgramCard key={p.id} p={p} lang={lang} rank={i+1} />)}</div><div className="split-grid"><div className="card panel"><div className="section-head compact"><h3>{tt(lang,'deadlines')}</h3><CalendarDays size={17}/></div>{journey.recommendations.slice(0,5).map((p:ScoredProgram)=><div className="deadline-line" key={p.id}><span className={`status-dot ${deadlineClass(p.deadlineStatus)}`}/><div><b>{p.university}</b><small>{p.deadline.value}</small></div><span className={`status-text ${deadlineClass(p.deadlineStatus)}`}>{deadlineLabel(p.deadlineStatus,lang)}</span></div>)}</div><div className="card panel"><div className="section-head compact"><h3>{tt(lang,'progress')}</h3><ListChecks size={17}/></div>{journey.roadmap.slice(0,4).map((t:any,i:number)=><div className="task-mini" key={t.id}><span className={t.status==='done'?'task-check done':'task-check'}>{t.status==='done'?<Check size={12}/>:i+1}</span><div><b>{t.title}</b><small>{t.due}</small></div></div>)}</div></div></section>}

function AIInsightCard({lang,profile,journey}:{lang:Lang;profile:Profile;journey:any}){const [data,setData]=useState<any>(null);const [loading,setLoading]=useState(false);const run=async()=>{setLoading(true);try{const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'analysis',profile,recommendations:journey.recommendations.slice(0,8).map((p:any)=>({id:p.id,university:p.university,program:p.program,fit:p.fit,tuition:p.tuition.value,ielts:p.ielts.value,sat:p.sat.value,gpa:p.gpa.value,scholarship:p.scholarship.value,deadline:p.deadline.value,country:p.country,description:p.description}))})});const x=await r.json();setData(x)}catch{setData({summary:'AI analysis is temporarily unavailable. Your Pathly Fit recommendations are still active.',actions:[]})}finally{setLoading(false)}};return <div className="ai-insight card"><div className="ai-insight-main"><div className="ai-orb"><Sparkles size={18}/></div><div><span className="eyebrow">PATHLY AI</span><h3>{data?.summary||'Get a second layer of analysis from your profile and current matches.'}</h3>{data?.actions?.length>0&&<div className="ai-actions">{data.actions.slice(0,3).map((x:string)=><span key={x}>{x}</span>)}</div>}</div></div><button className="primary-btn" onClick={run} disabled={loading}>{loading?'Analyzing…':'Analyze my route'}<ArrowRight size={15}/></button></div>}

function readinessLabel(fit:number){return fit>=82?'High':fit>=65?'Medium':'Low'}

const campusPhotos=[
 'https://images.unsplash.com/photo-1562774053-701939374585?auto=format&fit=crop&w=900&q=80',
 'https://images.unsplash.com/photo-1523050854058-8df90110c9f1?auto=format&fit=crop&w=900&q=80',
 'https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=900&q=80',
 'https://images.unsplash.com/photo-1606761568499-6d2451b23c66?auto=format&fit=crop&w=900&q=80',
 'https://images.unsplash.com/photo-1498243691581-b145c3f54a5a?auto=format&fit=crop&w=900&q=80'
];
function universityPhoto(id:string){let n=0;for(let i=0;i<id.length;i++)n=(n+id.charCodeAt(i))%campusPhotos.length;return campusPhotos[n]}
function ProgramCard({p,lang,rank}:{p:ScoredProgram;lang:Lang;rank:number}){return <article className="program-card card"><div className="program-photo"><img src={universityPhoto(p.id)} alt={`${p.university} campus`} loading="lazy"/><div className="photo-overlay"><span className="rank">0{rank}</span><span className="fit-chip">{p.fit} Fit</span></div></div><div className="program-card-body"><div className="card-top"><span className="tier">{p.tier}</span><span className="tier">{readinessLabel(p.fit)}</span></div><span className="loc">{p.city}, {p.country}</span><h3>{p.university}</h3><p className="program-name">{p.program}</p><p className="desc">{p.description}</p><div className="card-stats"><span><b>{p.ielts.value}</b><small>{tt(lang,'ielts')}</small></span><span><b>{p.sat.value}</b><small>{tt(lang,'sat')}</small></span><span><b>${Number(p.tuition.value||0).toLocaleString()}</b><small>{tt(lang,'budget')}</small></span></div><div className="requirements-strip"><span>GPA {p.gpa.value}</span><span>IELTS {p.ielts.value}</span><span>SAT {p.sat.value}</span></div><div className="card-bottom"><span>{String(p.scholarship.value)}</span><span className={`status-text ${deadlineClass(p.deadlineStatus)}`}>{p.deadline.value}</span></div></div></article>}

function matchesMultilingualQuery(p:any,q:string){const norm=q.toLowerCase().trim(); if(!norm)return true; const direct=[p.university,p.program,p.country, ...(p.tags||[])].join(' ').toLowerCase(); if(direct.includes(norm)) return true; return Object.entries(majorAliases).some(([major,aliases])=>p.program?.toLowerCase().includes(major.toLowerCase()) && (aliases as string[]).some(a=>a.toLowerCase().includes(norm)||norm.includes(a.toLowerCase())));}

function Explore({lang,profile,journey,selected,toggleSelected,setProfile,recalculate}:{lang:Lang;profile:Profile;journey:any;selected:string[];toggleSelected:(id:string)=>void;setProfile:(x:Partial<Profile>)=>void;recalculate:()=>void}){const [q,setQ]=useState('');const [country,setCountry]=useState('');const [global,setGlobal]=useState(false);const [items,setItems]=useState<any[]>([]);const [loading,setLoading]=useState(false);const [sort,setSort]=useState('fit');const [active,setActive]=useState<any>(null);const local=useMemo(()=>journey.recommendations.filter((p:any)=>matchesMultilingualQuery(p,q)).filter((p:any)=>!country||p.country===country).sort((a:any,b:any)=>sort==='fit'?b.fit-a.fit:sort==='cost'?Number(a.tuition.value)-Number(b.tuition.value):new Date(a.deadline.iso||'2100-01-01').getTime()-new Date(b.deadline.iso||'2100-01-01').getTime()),[journey.recommendations,q,country,sort]); useEffect(()=>{let off=false;if(!global||q.length<2){setItems([]);return}setLoading(true);fetch(`/api/universities?q=${encodeURIComponent(q)}${country?`&country=${encodeURIComponent(country)}`:''}`).then(r=>r.json()).then(x=>{if(!off)setItems(x.items||[])}).catch(()=>setItems([])).finally(()=>!off&&setLoading(false));return()=>{off=true}},[q,country,global]);return <section><div className="hero-heading"><div><span className="eyebrow">DISCOVERY</span><h1>{tt(lang,'explore')}</h1><p>{tt(lang,'search')}</p></div><div className="search-wrap"><Search size={17}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder={tt(lang,'search')}/></div></div><div className="explore-toolbar"><div className="filter-row"><select value={country} onChange={e=>setCountry(e.target.value)}><option value="">{tt(lang,'all')}</option>{countries.map(c=><option key={c}>{c}</option>)}</select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="fit">{tt(lang,'fit')}</option><option value="cost">{tt(lang,'cost')}</option><option value="deadline">{tt(lang,'deadline')}</option></select><button className={global?'secondary-btn active-filter':'secondary-btn'} onClick={()=>setGlobal(!global)}><Globe2 size={14}/>{tt(lang,'global')}</button></div><div className="result-count">{local.length} curated programs{global&&items.length?` · ${items.length} global results`:''}</div></div><div className="program-grid">{local.map((p:any,i:number)=><button className="program-button" key={p.id} onClick={()=>setActive(p)}><ProgramCard p={p} lang={lang} rank={i+1}/></button>)}</div>{global&&<div className="global-panel card"><div className="section-head"><div><span className="eyebrow">{tt(lang,'directory')}</span><h2>{loading?'Searching…':`${items.length} global results`}</h2></div><Globe2 size={18}/></div>{!items.length&&!loading?<div className="empty-state">Try a more specific university or country query.</div>:<div className="global-list">{items.map((item:any)=><button key={`${item.name}-${item.country}`} className="global-row" onClick={()=>setActive(item)}><div className="avatar">{(item.name||'U')[0]}</div><div><b>{item.name}</b><small>{item.country} · {item.domains?.[0]||'Global directory'}</small></div><ChevronRight size={16}/></button>)}</div>}</div>}{active&&<UniversityModal lang={lang} item={active} close={()=>setActive(null)} selected={selected} toggleSelected={toggleSelected}/>}</section>}

function UniversityModal({lang,item,close,selected,toggleSelected}:{lang:Lang;item:any;close:()=>void;selected:string[];toggleSelected:(id:string)=>void}){const local=Boolean(item.program);return <div className="modal-backdrop" onMouseDown={close}><div className="modal large-modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">{local?'PATHLY PROGRAM':'GLOBAL DIRECTORY'}</span><h2>{item.university||item.name}</h2><p>{local?`${item.program} · ${item.city}, ${item.country}`:`${item.country} · ${item.domains?.[0]||'Worldwide directory entry'}`}</p></div><button className="icon-btn" onClick={close}><X size={18}/></button></div>{local?<><div className="university-modal-photo"><img src={universityPhoto(item.id)} alt={`${item.university} campus`} /></div><div className="detail-grid"><div><span>{tt(lang,'description')}</span><p>{item.description}</p></div><div><span>{tt(lang,'requirements')}</span><p>IELTS {item.ielts.value} · SAT {item.sat.value} · GPA {item.gpa.value}</p></div><div><span>{tt(lang,'scholarships')}</span><p>{item.scholarship.value}</p><small>{item.scholarshipTypes?.join(' · ')}</small></div><div><span>{tt(lang,'deadlineStatus')}</span><p>{item.deadline.value} · <b className={`status-text ${deadlineClass(item.deadlineStatus)}`}>{deadlineLabel(item.deadlineStatus,lang)}</b></p></div></div><div className="why-box"><h3>Why this program?</h3>{item.wins?.map((w:string)=><div key={w}><Check size={14}/>{w}</div>)}{item.gaps?.map((g:string)=><div className="warn" key={g}><Target size={14}/>{g}</div>)}</div><div className="info-note"><CircleHelp size={15}/><span>{tt(lang,'demo')}: verify requirements, scholarships and deadlines on the official university page before applying.</span></div><div className="modal-actions">{item.applicationUrl&&<a className="primary-btn" href={item.applicationUrl} target="_blank">Official site <ExternalLink size={15}/></a>}<button className="secondary-btn" onClick={()=>toggleSelected(item.id)}>{selected.includes(item.id)?<Check size={15}/>:<Heart size={15}/>} {selected.includes(item.id)?'Saved':tt(lang,'shortlist')}</button></div></>:<><div className="detail-grid"><div><span>{tt(lang,'country')}</span><p>{item.country}</p></div><div><span>Website</span><p>{item.webPages?.[0]||'—'}</p></div><div><span>Domain</span><p>{item.domains?.join(', ')||'—'}</p></div><div><span>{tt(lang,'programs')}</span><p>Program-level details require verification.</p></div></div><div className="info-note"><Globe2 size={15}/><span>Global directory data is for discovery. Detailed admissions facts appear only on curated records.</span></div></>}</div></div>}

function Shortlist({lang,journey,selected,toggleSelected}:{lang:Lang;journey:any;selected:string[];toggleSelected:(id:string)=>void}){const chosen=journey.recommendations.filter((p:any)=>selected.includes(p.id));return <section><div className="hero-heading"><div><span className="eyebrow">SHORTLIST</span><h1>{tt(lang,'compare')}</h1><p>{selected.length} {tt(lang,'programs').toLowerCase()} selected.</p></div></div>{!chosen.length?<div className="empty card"><Heart size={22}/><h3>{tt(lang,'shortlist')}</h3><p>Explore the directory and save at least two programs.</p></div>:<><div className="compare-grid">{chosen.map((p:any)=><article className="compare-card card" key={p.id}><div className="card-top"><span className="tier">{p.tier}</span><span className="fit-chip">{p.fit}</span><span className="tier">{readinessLabel(p.fit)}</span></div><h3>{p.university}</h3><p>{p.program}</p><div className="compare-list"><span>IELTS <b>{p.ielts.value}</b></span><span>SAT <b>{p.sat.value}</b></span><span>Tuition <b>${Number(p.tuition.value||0).toLocaleString()}</b></span><span>Funding <b>{p.scholarship.value}</b></span><span>{tt(lang,'deadline')} <b>{p.deadline.value}</b></span></div><button className="secondary-btn" onClick={()=>toggleSelected(p.id)}><Trash2 size={14}/>Remove</button></article>)}</div><div className="card compare-table-wrap"><div className="section-head compact"><h3>{tt(lang,'compare')}</h3><SlidersHorizontal size={16}/></div><div className="compare-table">{['Pathly Fit','Tuition','IELTS','SAT','Funding','Deadline status'].map(label=><div className="compare-tr" key={label}><strong>{label}</strong>{chosen.map((p:any)=><span key={p.id}>{label==='Pathly Fit'?p.fit:label==='Tuition'?`$${Number(p.tuition.value||0).toLocaleString()}`:label==='IELTS'?p.ielts.value:label==='SAT'?p.sat.value:label==='Funding'?p.scholarship.value:deadlineLabel(p.deadlineStatus,lang)}</span>)}</div>)}</div></div></>}</section>}

function Roadmap({lang,journey,pct,completeTask}:{lang:Lang;journey:any;pct:number;completeTask:(id:string)=>void}){return <section><div className="hero-heading"><div><span className="eyebrow">ROADMAP</span><h1>{tt(lang,'roadmap')}</h1><p>From today to application day — one deliberate action at a time.</p></div><div className="big-progress card"><span>{tt(lang,'progress')}</span><b>{pct}%</b><div className="progress"><span style={{width:`${pct}%`}}/></div></div></div><div className="timeline">{journey.roadmap.map((t:any,i:number)=><div className={`timeline-item ${t.status==='done'?'done':''}`} key={t.id}><div className="timeline-marker">{t.status==='done'?<CheckCircle2 size={16}/>:<span>{i+1}</span>}</div><div className="card task-card"><div><span className={`priority ${t.priority.toLowerCase()}`}>{t.priority}</span><h3>{t.title}</h3><p>{t.why}</p><small><Clock3 size={13}/>{t.due}</small></div><button className={t.status==='done'?'task-btn done':'task-btn'} onClick={()=>completeTask(t.id)}>{t.status==='done'?<Check size={15}/>:<Check size={15}/>}</button></div></div>)}</div></section>}

function Funding({lang,journey}:{lang:Lang;journey:any}){const list=journey.recommendations.filter((p:any)=>String(p.scholarship.value).toLowerCase().includes('full')||String(p.scholarship.value).toLowerCase().includes('tuition'));return <section><div className="hero-heading"><div><span className="eyebrow">FUNDING</span><h1>{tt(lang,'scholarships')}</h1><p>Scholarships connected to your current route.</p></div></div><div className="funding-grid">{list.map((p:any)=><article className="card funding-card" key={p.id}><div className="funding-icon"><Trophy size={17}/></div><span className="loc">{p.country}</span><h3>{p.university}</h3><p>{p.scholarship.value}</p><div className="tag-row">{p.scholarshipTypes?.map((x:string)=><span className="tag" key={x}>{x}</span>)}</div><div className="funding-meta"><span>Fit <b>{p.fit}</b></span><span>{p.deadline.value}</span></div><small>{tt(lang,'demo')} · {tt(lang,'source')}</small></article>)}</div></section>}

function ProfileView({lang,profile,setProfile,recalculate}:{lang:Lang;profile:Profile;setProfile:(p:Partial<Profile>)=>void;recalculate:()=>void}){const update=(patch:Partial<Profile>)=>setProfile(patch); const [newActivity,setNewActivity]=useState(''); const [newAchievement,setNewAchievement]=useState(''); return <section><div className="hero-heading"><div><span className="eyebrow">PROFILE</span><h1>{tt(lang,'profile')}</h1><p>Every edit can change your recommendations and roadmap.</p></div><button className="primary-btn" onClick={recalculate}><Sparkles size={15}/>{tt(lang,'recalculate')}</button></div><div className="profile-editor card"><div className="profile-head"><div className="avatar large">A</div><div><h3>Alex</h3><p>{profile.country} · {profile.degree} · {profile.targetIntake}</p></div></div><div className="form-grid big"><NumberField label={tt(lang,'age')} value={profile.age} min={14} max={100} step={1} onChange={v=>update({age:v})}/><Select label={tt(lang,'grade')} value={profile.grade} options={['Grade 9','Grade 10','Grade 11','Grade 12','Graduate']} onChange={v=>update({grade:v})}/><Select label={tt(lang,'degree')} value={profile.degree} options={['Bachelor','Master']} onChange={v=>update({degree:v as any})}/><Select label={tt(lang,'major')} value={profile.major} options={majors} onChange={v=>update({major:v})}/><Select label={tt(lang,'country')} value={profile.country} options={countries} onChange={v=>update({country:v})}/><Select label={tt(lang,'year')} value={profile.targetYear} options={Array.from({length:10},(_,i)=>2026+i)} onChange={v=>update({targetYear:Number(v)})}/><NumberField label={tt(lang,'gpa')} value={profile.gpa} min={1} max={5} step={0.1} onChange={v=>update({gpa:v})}/><NumberField label={tt(lang,'ielts')} value={profile.ielts} min={0} max={9} step={0.5} onChange={v=>update({ielts:v})}/><NumberField label={tt(lang,'sat')} value={profile.sat} min={400} max={1600} step={10} onChange={v=>update({sat:v})}/><BudgetField label={tt(lang,'budget')} value={profile.budget} onChange={v=>update({budget:v})}/><Select label="Intake" value={profile.targetIntake} options={['Spring 2027','Fall 2027','Spring 2028','Fall 2028']} onChange={v=>update({targetIntake:v})}/><Select label="Goal" value={profile.goal} options={['fully-funded','top-academic','study-abroad','career']} onChange={v=>update({goal:v as any})}/></div><div className="toggle-card"><div><b>{tt(lang,'fully')}</b><small>Prioritize programs with strong funding signals.</small></div><button className={profile.fullyFunded?'switch on':'switch'} onClick={()=>update({fullyFunded:!profile.fullyFunded})}><span/></button></div><div className="profile-two-col"><div className="interest-block"><label>{tt(lang,'interests')}</label><div className="tag-cloud">{['AI','Software','Research','Robotics','Entrepreneurship','Physics','Design','Data'].map(x=><button key={x} className={profile.interests.includes(x)?'tag active':'tag'} onClick={()=>update({interests:profile.interests.includes(x)?profile.interests.filter(i=>i!==x):[...profile.interests,x]})}>{x}</button>)}</div></div><div className="country-picks"><label>Preferred countries</label><div className="country-cloud">{profile.preferredCountries.map(c=><button key={c} className="country-chip" onClick={()=>update({preferredCountries:profile.preferredCountries.filter(x=>x!==c)})}>{c} <X size={11}/></button>)}<CountryAdd profile={profile} update={update}/></div></div></div><div className="profile-two-col"><EditableList title={tt(lang,'achievements')} items={profile.achievements} value={newAchievement} setValue={setNewAchievement} onAdd={()=>{if(newAchievement.trim())update({achievements:[...profile.achievements,newAchievement.trim()]});setNewAchievement('')}} onRemove={(x)=>update({achievements:profile.achievements.filter(i=>i!==x)})} placeholder={tt(lang,'emptyAchievements')}/><EditableList title={tt(lang,'activities')} items={profile.activities} value={newActivity} setValue={setNewActivity} onAdd={()=>{if(newActivity.trim()&&!profile.activities.includes(newActivity.trim()))update({activities:[...profile.activities,newActivity.trim()]});setNewActivity('')}} onRemove={(x)=>update({activities:profile.activities.filter(i=>i!==x)})} placeholder="Add clubs, volunteering, projects or leadership."/></div></div></section>}

function EditableList({title,items,value,setValue,onAdd,onRemove,placeholder}:{title:string;items:string[];value:string;setValue:(x:string)=>void;onAdd:()=>void;onRemove:(x:string)=>void;placeholder:string}){return <div className="editable-box"><div className="section-head compact"><h3>{title}</h3><Plus size={16}/></div><p>{placeholder}</p><div className="editable-list">{items.map(x=><span className="editable-chip" key={x}>{x}<button onClick={()=>onRemove(x)}><X size={11}/></button></span>)}</div><div className="inline-add"><input value={value} onChange={e=>setValue(e.target.value)} placeholder="Add…"/><button onClick={onAdd}><Plus size={14}/></button></div></div>}
function CountryAdd({profile,update}:{profile:Profile;update:(p:Partial<Profile>)=>void}){const [v,setV]=useState('');const add=()=>{if(v&&!profile.preferredCountries.includes(v))update({preferredCountries:[...profile.preferredCountries,v]});setV('')};return <div className="country-add"><select value={v} onChange={e=>setV(e.target.value)}><option value="">+ country</option>{countries.filter(c=>!profile.preferredCountries.includes(c)).map(c=><option key={c}>{c}</option>)}</select><button onClick={add}><Check size={14}/></button></div>}
function LanguageMenu({lang,setLang}:{lang:Lang;setLang:(v:Lang)=>void}){
 const [open,setOpen]=useState(false);
 const current=languageOptions.find(x=>x.id===lang)?.label||'English';
 return <div className={`language-menu ${open?'open':''}`}>
  <button type="button" className="language-trigger" aria-haspopup="listbox" aria-expanded={open} onClick={()=>setOpen(v=>!v)}><span>{current}</span><ChevronDown size={15}/></button>
  {open&&<div className="language-dropdown" role="listbox">{languageOptions.map(x=><button type="button" role="option" aria-selected={x.id===lang} className={x.id===lang?'active':''} key={x.id} onClick={()=>{setLang(x.id as Lang);setOpen(false)}}>{x.label}{x.id===lang&&<Check size={14}/>}</button>)}</div>}
 </div>
}

function NumberField({label,value,min,max,step,onChange}:{label:string;value:number;min:number;max:number;step:number;onChange:(v:number)=>void}){
 const [draft,setDraft]=useState(String(value));
 useEffect(()=>setDraft(String(value)),[value]);
 const commit=()=>{
  const parsed=Number(draft);
  const next=Number.isFinite(parsed)?Math.min(max,Math.max(min,parsed)):value;
  const precision=step<1?10:1;
  const stepped=Math.round((next-min)/step)*step+min;
  const normalized=Math.min(max,Math.max(min,Math.round(stepped*precision)/precision));
  setDraft(String(normalized));
  if(normalized!==value) onChange(normalized);
 };
 return <label className="field number-field"><span>{label}</span><input type="number" inputMode="decimal" min={min} max={max} step={step} value={draft} onChange={e=>setDraft(e.target.value)} onBlur={commit} onKeyDown={e=>{if(e.key==='Enter'){e.currentTarget.blur()}}} aria-label={`${label}, from ${min} to ${max}`}/><small>{min}–{max}</small></label>
}

function Select({label,value,options,onChange}:{label:string;value:any;options:any[];onChange:(v:string)=>void}){return <label className="field"><span>{label}</span><select value={String(value)} onChange={e=>onChange(e.target.value)}>{options.map(o=><option key={String(o)} value={String(o)}>{String(o)}</option>)}</select></label>}
function BudgetField({label,value,onChange}:{label:string;value:number|null;onChange:(v:number|null)=>void}){const [draft,setDraft]=useState(value==null?'Flexible':String(value));useEffect(()=>setDraft(value==null?'Flexible':String(value)),[value]);const commit=()=>{const raw=draft.trim();if(!raw||/^flexible$/i.test(raw)){setDraft('Flexible');onChange(null);return}const n=Number(raw.replace(/[$,\s]/g,''));if(Number.isFinite(n)&&n>=0){const next=Math.round(n);setDraft(String(next));onChange(next)}else setDraft(value==null?'Flexible':String(value))};return <label className="field budget-field"><span>{label}</span><div className="budget-input-wrap"><input value={draft} onChange={e=>setDraft(e.target.value)} onBlur={commit} onKeyDown={e=>{if(e.key==='Enter')e.currentTarget.blur()}} placeholder="Flexible or amount"/><button type="button" className={value==null?'budget-flex active':'budget-flex'} onClick={()=>{setDraft('Flexible');onChange(null)}}>Flexible</button></div><small>Enter an amount or use Flexible.</small></label>}
function ChatModal({lang,profile,close}:{lang:Lang;profile:Profile;close:()=>void}){const [messages,setMessages]=useState<{role:'user'|'bot';text:string;recommendations?:any[]}[]>([{role:'bot',text:'Hi! I can analyze your profile, explain matches, compare universities and suggest what to do next.'}]);const [input,setInput]=useState('');const [loading,setLoading]=useState(false);const send=async()=>{const text=input.trim();if(!text||loading)return;setMessages(m=>[...m,{role:'user',text}]);setInput('');setLoading(true);try{const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'chat',message:text,profile})});const data=await r.json();setMessages(m=>[...m,{role:'bot',text:data.summary||'I can help with your route.',recommendations:data.recommendations||[]}])}catch{setMessages(m=>[...m,{role:'bot',text:'Pathly is temporarily offline. Try again in a moment.'}])}finally{setLoading(false)}};return <div className="modal-backdrop" onMouseDown={close}><div className="chat-modal modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow"><Sparkles size={13}/> PATHLY AI</span><h2>Ask Pathly</h2><p>Advice, profile analysis and university suggestions based on your current data.</p></div><button className="icon-btn" onClick={close}><X size={18}/></button></div><div className="chat-messages">{messages.map((m,i)=><div key={i} className={`chat-message ${m.role}`}><div>{m.text}</div>{m.recommendations?.length>0&&<div className="chat-recs">{m.recommendations.slice(0,3).map((p:any)=><div className="chat-rec" key={p.id||p.university}><img src={universityPhoto(p.id||p.university)} alt=""/><div><b>{p.university}</b><small>{p.program||p.reason||''}</small></div></div>)}</div>}</div>)}{loading&&<div className="chat-message bot typing">Thinking…</div>}</div><div className="chat-suggestions"><button onClick={()=>setInput('Which universities fit me best?')}>Best matches</button><button onClick={()=>setInput('What is my biggest gap?')}>My biggest gap</button><button onClick={()=>setInput('How can I improve my chances?')}>Next steps</button></div><div className="chat-composer"><input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')send()}} placeholder="Ask about a university, requirements, funding…"/><button className="primary-btn" onClick={send} disabled={loading||!input.trim()}><ArrowRight size={16}/></button></div></div></div>}

function SettingsModal({lang,setLang,theme,setTheme,density,setDensity,close}:{lang:Lang;setLang:(v:Lang)=>void;theme:Theme;setTheme:(v:Theme)=>void;density:Density;setDensity:(v:Density)=>void;close:()=>void}){return <div className="modal-backdrop" onMouseDown={close}><div className="settings modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">SETTINGS</span><h2>{tt(lang,'profile')}</h2></div><button className="icon-btn" onClick={close}><X size={18}/></button></div><div className="setting"><div><b>{tt(lang,'language')}</b><small>All interface labels use the selected language.</small></div><LanguageMenu lang={lang} setLang={setLang}/></div><div className="setting"><div><b>{tt(lang,'theme')}</b><small>{theme==='dark'?tt(lang,'dark'):tt(lang,'light')}</small></div><div className="segmented"><button className={theme==='dark'?'active':''} onClick={()=>setTheme('dark')}><Moon size={14}/>{tt(lang,'dark')}</button><button className={theme==='light'?'active':''} onClick={()=>setTheme('light')}><Sun size={14}/>{tt(lang,'light')}</button></div></div><div className="setting"><div><b>{tt(lang,'size')}</b><small>Change spacing and text scale.</small></div><div className="segmented"><button className={density==='compact'?'active':''} onClick={()=>setDensity('compact')}><ZoomOut size={14}/>{tt(lang,'compact')}</button><button className={density==='comfortable'?'active':''} onClick={()=>setDensity('comfortable')}><ChevronRight size={14}/>{tt(lang,'comfortable')}</button><button className={density==='large'?'active':''} onClick={()=>setDensity('large')}><ZoomIn size={14}/>{tt(lang,'large')}</button></div></div><div className="info-note"><Languages size={15}/><span>Search understands common major names and aliases in multiple languages.</span></div></div></div>}
